$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSScriptRoot);$stamp=[DateTime]::UtcNow.ToString('yyyyMMddHHmmssfff');$u="qa.pago.$stamp";$pw='Temporal-QA-'+[guid]::NewGuid().ToString('N');$mail="$u@example.test";$ref="QA-REF-$stamp";$ids=@{};$checks=@();$gp=$null
function C($n,$ok,$d){$script:checks+=[pscustomobject]@{prueba=$n;estado=if($ok){'PASS'}else{'HUECO'};detalle=$d}}
function S($q){$r=& sqlcmd -S MADRENZO -d LavaFacil -E -C -I -b -h -1 -W -Q $q 2>&1;if($LASTEXITCODE-ne 0){throw($r-join"`n")};$r}
function G($q,$t=$null){$h=@{};if($t){$h.Authorization="Bearer $t"};$b=@{query=$q}|ConvertTo-Json -Compress;return Invoke-RestMethod -Uri http://127.0.0.1:5125/graphql -Method Post -ContentType application/json -Headers $h -Body $b}
try{
 $setup="DECLARE @e INT;INSERT dbo.Empleados(Cedula,Nombre,Apellidos,Telefono,Email,Cargo,FechaIngreso) VALUES('QA$stamp','QA','Pago','5551234567','$mail','Administrador',CONVERT(date,GETDATE()));SET @e=SCOPE_IDENTITY();EXEC dbo.InsertarUsuario @NombreUsuario='$u',@Clave='$pw',@TipoUsuario='Administrador',@IdCliente=NULL,@IdEmpleado=@e;SELECT @e,(SELECT IdUsuario FROM dbo.Usuarios WHERE NombreUsuario='$u');";$row=@(& sqlcmd -S MADRENZO -d LavaFacil -E -C -I -b -h -1 -W -s '|' -Q $setup 2>&1)|?{$_ -match '\|'}|select -Last 1;$p=$row-split'\|';$ids.e=[int]$p[0];$ids.u=[int]$p[1]
 $env:ConnectionStrings__Empleado='Server=MADRENZO;Database=LavaFacil;Integrated Security=True;TrustServerCertificate=True';$env:ConnectionStrings__Cliente=$env:ConnectionStrings__Empleado;$env:ConnectionStrings__Invitado=$env:ConnectionStrings__Empleado;$env:ASPNETCORE_URLS='http://127.0.0.1:5125';$gpath=Join-Path $root 'Proyecto2\03-Backend-GraphQL\LavaFacil.GraphQL\bin\Release\net9.0\LavaFacil.GraphQL.dll';$gp=Start-Process dotnet -ArgumentList ('"'+$gpath+'"') -WorkingDirectory (Join-Path $root 'Proyecto2\03-Backend-GraphQL\LavaFacil.GraphQL') -PassThru;Start-Sleep 8
  $l=G "mutation { login(usuario: `"$u`", clave: `"$pw`") { exito token mensaje } }";$jwt=$l.data.login.token;C 'login GraphQL JWT temporal' ($l.data.login.exito -and $jwt) ($l|ConvertTo-Json -Compress);if(-not $jwt){throw 'JWT temporal no disponible'}
 $ced="QAC$stamp";$svc="QA Servicio $stamp";G "mutation { insertarCliente(cedula: `"$ced`", nombre: `"QA`", apellidos: `"Pago`", telefono: `"5551234567`", email: `"$mail`", direccion: `"Temporal`") { exito mensaje } }" $jwt|Out-Null;$ids.c=(G '{clientes{idCliente cedula}}' $jwt).data.clientes|? cedula -eq $ced|select -Expand idCliente
 G "mutation { insertarServicio(nombreServicio: `"$svc`", descripcion: `"Temporal`", tipoCobro: `"Servicio`", precioBase: 100, cantidadIncluida: 1, precioAdicional: 0) { exito mensaje } }" $jwt|Out-Null;$ids.s=(G '{servicios{idServicio nombreServicio}}' $jwt).data.servicios|? nombreServicio -eq $svc|select -Expand idServicio
 G "mutation { insertarPedido(idCliente: $($ids.c), fechaEntregaEstimada: `"2026-11-10T12:00:00Z`", estado: `"Pendiente`", total: 123.45, observaciones: `"$ref`") { exito mensaje } }" $jwt|Out-Null;$ids.p=(G '{pedidos{idPedido observaciones}}' $jwt).data.pedidos|? observaciones -eq $ref|select -Expand idPedido
 G "mutation { insertarDetallePedido(idPedido: $($ids.p), idServicio: $($ids.s), cantidad: 1, precioBase: 123.45, montoAdicional: 0, subtotal: 123.45) { exito mensaje } }" $jwt|Out-Null;G "mutation { insertarPago(idPedido: $($ids.p), monto: 123.45, metodoPago: `"Tarjeta`", estadoPago: `"Pendiente`", referencia: `"$ref`") { exito mensaje } }" $jwt|Out-Null;$ids.g=(G '{pagos{idPago referencia}}' $jwt).data.pagos|? referencia -eq $ref|select -Expand idPago
 $m="mutation { actualizarPago(idPago: $($ids.g), idPedido: $($ids.p), monto: 123.45, metodoPago: `"Tarjeta`", estadoPago: `"Pagado`", referencia: `"$ref`") { exito mensaje } }";$a=G $m $jwt;Start-Sleep 12;$q=(S "SELECT p.Estado,ce.Tipo,ce.DatosJson FROM dbo.Pagos p LEFT JOIN dbo.CorreoEnvios ce ON ce.IdPago=p.IdPago WHERE p.IdPago=$($ids.g) FOR JSON PATH;")-join'';$b=G $m $jwt;$n=[regex]::Matches($q,'ComprobantePago|PagoConfirmado').Count;C 'ActualizarPago real Pagado' ($a.data.actualizarPago.exito-and$q-match'Pagado') $q;C 'exactamente un CorreoEnvios pago' ($n-eq 1) "count=$n; $q";C 'monto metodo referencia' ($q-match'123.45'-and$q-match'Tarjeta'-and$q-match$ref) $q;C 'repetir Pagado no duplica' ($b.data.actualizarPago.exito-and$n-eq 1) "count=$n"
 G "mutation { insertarPedido(idCliente: $($ids.c), fechaEntregaEstimada: `"2026-11-10T12:00:00Z`", estado: `"Pendiente`", total: 20, observaciones: `"$ref-OTRO`") { exito mensaje } }" $jwt|Out-Null;$ids.o=(G '{pedidos{idPedido observaciones}}' $jwt).data.pedidos|? observaciones -eq "$ref-OTRO"|select -Expand idPedido;$w=G "mutation { actualizarPago(idPago: $($ids.g), idPedido: $($ids.o), monto: 123.45, metodoPago: `"Tarjeta`", estadoPago: `"Pagado`", referencia: `"$ref`") { exito mensaje } }" $jwt;C 'pago de otro pedido rechaza' (-not $w.data.actualizarPago.exito) $w.data.actualizarPago.mensaje
}catch{C 'flujo pago autenticado' $false $_.Exception.Message}
finally{if($gp){try{$gp.Kill()}catch{}};try{S "DELETE FROM dbo.CorreoEnvios WHERE IdPago IN(SELECT IdPago FROM dbo.Pagos WHERE Referencia='$ref') OR IdPedido IN(SELECT IdPedido FROM dbo.Pedidos WHERE Observaciones LIKE '$ref%');DELETE FROM dbo.Pagos WHERE Referencia='$ref' OR IdPedido IN(SELECT IdPedido FROM dbo.Pedidos WHERE Observaciones LIKE '$ref%');DELETE FROM dbo.DetallePedido WHERE IdPedido IN(SELECT IdPedido FROM dbo.Pedidos WHERE Observaciones LIKE '$ref%');DELETE FROM dbo.Pedidos WHERE Observaciones LIKE '$ref%';DELETE FROM dbo.TokensCorreo WHERE IdUsuario IN(SELECT IdUsuario FROM dbo.Usuarios WHERE NombreUsuario='$u');DELETE FROM dbo.Usuarios WHERE NombreUsuario='$u';DELETE FROM dbo.Empleados WHERE Email='$mail';"|Out-Null}catch{C 'limpieza BD' $false $_.Exception.Message};$checks|ConvertTo-Json -Depth 5|Set-Content (Join-Path $PSScriptRoot 'pago-real.json')}

